#!/usr/bin/env bash
# Full-chain E2E for the readiness bridge:
#
#   the probe chain (probe.uproc, probe_collect.uproc) drives an exec readiness probe through the sandbox runtime's
#   /sandbox-exec/ seam and writes /probe-status/<uid> = live=..;ready=..
#          │  (the verdict, keyed by pod uid)
#          ▼
#   joins that verdict onto the k8s Pod object at
#   /pods/<ns>/<name> by metadata.uid, and the verdict OVERRIDES the pod's
#   Pod's own Ready condition when selecting a Service's endpoints
#          │
#          ▼
#   the pod appears in / stays out of /endpoints/<ns>/<name>
#
# This is the hop from a probe verdict to endpoint membership.
# All four modules run in ONE runtime over the shared store, so a REAL probe
# flip propagates to endpoints selection — nothing is hand-seeded on
# /probe-status/.
#
# Two pods behind Service default/web (selector app=web), each seeded with a
# k8s Pod object carrying metadata.uid:
#   web-ready  rp_cmd=/bin/true        static Ready condition False
#              → probe flips ready 0→1 → OVERRIDE includes it (proves the probe,
#                not the static field, put it in the endpoint set)
#   web-fail   rp_cmd=/bin/false       static Ready condition True
#              → probe holds ready=0 → OVERRIDE excludes it (proves the probe can
#                pull a statically-ready pod OUT)
#
# Runs UNPRIVILEGED (null sandboxes; exec is the already-shipped seam).
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
MODULES_DIR="$ROOT/target/fluxor/aarch64/modules"

. "$ROOT/scripts/fluxor-env.sh"
# The container runtime, as the packaged sandbox graph states it.
SANDBOX_MODS="$(python3 "$ROOT/scripts/support/sandbox-block.py" mods)"
SANDBOX_WIRE="$(python3 "$ROOT/scripts/support/sandbox-block.py" wire)"
if [ -z "${FLUXOR_RUNTIME:-}" ]; then
  FLUXOR_RUNTIME="$(nc_fluxor_runtime "$ROOT")"
fi

command -v fluxor >/dev/null || { echo "FAIL: fluxor CLI not on PATH (cargo install --locked --path ../fluxor/tools)"; exit 1; }
for f in "$FLUXOR_RUNTIME" \
         "$MODULES_DIR/workload_effect.fmod" \
         ; do
  [ -e "$f" ] || { echo "FAIL: missing $f (fluxor modules build --target bcm2712)"; exit 1; }
done

D="$(mktemp -d /tmp/nc-probe-ep-e2e-XXXXXX)"
trap 'rm -rf "$D"' EXIT
fail() { echo "FAIL: $1"; tail -25 "$D/run.log" 2>/dev/null || true; exit 1; }

# Append one put record to the store's durable log (same wire the store writes:
# [rev:u64][op:u8=1][key_len:u16][val_len:u32][key][val]). Single-writer here —
# no flock, because nothing else has the file open (the runtime is not running).
store_put() { # store_put <key> <value>
  python3 - "$D/store.log" "$1" "$2" <<'PY'
import struct, sys, os
path, key, val = sys.argv[1], sys.argv[2].encode(), sys.argv[3].encode()
fd = os.open(path, os.O_RDWR | os.O_CREAT, 0o644)
with os.fdopen(fd, "r+b") as f:
    data = f.read()
    p, last = 0, 0
    while p + 15 <= len(data):
        rev, op, kl, vl = struct.unpack("<QBHI", data[p:p+15])
        if p + 15 + kl + vl > len(data):
            break
        last, p = rev, p + 15 + kl + vl
    f.truncate(p)
    f.seek(0, 2)
    f.write(struct.pack("<QBHI", last + 1, 1, len(key), len(val)) + key + val)
    f.flush(); os.fsync(f.fileno())
PY
}

store_last() { # store_last <key>  — last-writer value of a key in the log
  python3 - "$D/store.log" "$1" <<'PY'
import struct, sys
data = open(sys.argv[1], "rb").read()
want = sys.argv[2].encode()
p, out = 0, None
while p + 15 <= len(data):
    rev, op, kl, vl = struct.unpack("<QBHI", data[p:p+15])
    if p + 15 + kl + vl > len(data):
        break
    k = data[p+15:p+15+kl]; v = data[p+15+kl:p+15+kl+vl]
    if k == want:
        out = v if op == 1 else None
    p += 15 + kl + vl
print(out.decode() if out is not None else "")
PY
}

store_history() { # store_history <key> — every value ever put, one per line
  python3 - "$D/store.log" "$1" <<'PY'
import struct, sys
data = open(sys.argv[1], "rb").read()
want = sys.argv[2].encode()
p = 0
while p + 15 <= len(data):
    rev, op, kl, vl = struct.unpack("<QBHI", data[p:p+15])
    if p + 15 + kl + vl > len(data):
        break
    k = data[p+15:p+15+kl]; v = data[p+15+kl:p+15+kl+vl]
    if k == want and op == 1:
        print(v.decode(errors="replace"))
    p += 15 + kl + vl
PY
}

echo "== 1. compose the full-chain graph (+ the sandbox runtime + the probe chain + the endpoints chain) =="
cat > "$D/graph.yaml" <<'YAML'
# Full-chain readiness-bridge fixture: the
# pod-lifecycle pipeline plus the endpoints reconciler, all over the one store.
target: linux
tick_us: 1000
scheduler:
  accept_cycles: true
modules:
${SANDBOX_MODS}
  # Liveness/readiness probes are PARAMS (probe.uproc, probe_collect.uproc):
  # per-probe state at /probe-rt-<l|r>/<uid> (its due/deadline arm the timer),
  # exec attempts over the /sandbox-exec/ seam, verdicts at /probe-status/.
  - name: pb_spec
    type: store_source
    prefix: "/pod-probes/"
    flat: 1
    paths: "lp_cmd,rp_cmd,sp_cmd"
  - name: pb_seed_l
    type: store_effect
    # chronicle-source: modules/app/_chronicle/probe.uproc sd_l
    decision: {hex: ""}
  - name: pb_seed_r
    type: store_effect
    # chronicle-source: modules/app/_chronicle/probe.uproc sd_r
    decision: {hex: ""}
  - name: pb_tl
    type: store_source
    prefix: "/probe-rt-l/"
    flat: 1
    ints: "inflight,due,deadline,seq,fails,oks,verdict"
    now: 1
    due: "due,deadline"
    related: "/pod-probes/!flat:lp_cmd,lp_period#,lp_timeout#,lp_fail#,lp_succ#,lp_delay#;/sandbox-status/!flat:state;/probe-rt-s/!flat:seq,verdict#"
    watch: "/pod-probes/,/sandbox-status/,/probe-rt-"
  - name: pb_tl_rt
    type: store_effect
    # chronicle-source: modules/app/_chronicle/probe.uproc tk_l
    decision: {hex: ""}
    key_prefix: "/probe-rt-l/"
  - name: pb_tl_res
    type: store_effect
    # chronicle-source: modules/app/_chronicle/probe.uproc sm_res
    decision: {hex: ""}
  - name: pb_tl_out
    type: store_effect
    # chronicle-source: modules/app/_chronicle/probe.uproc sm_out
    decision: {hex: ""}
  - name: pb_tl_req
    type: store_effect
    # chronicle-source: modules/app/_chronicle/probe.uproc sm_req
    decision: {hex: ""}
  - name: pb_tr
    type: store_source
    prefix: "/probe-rt-r/"
    flat: 1
    ints: "inflight,due,deadline,seq,fails,oks,verdict"
    now: 1
    due: "due,deadline"
    related: "/pod-probes/!flat:rp_cmd,rp_period#,rp_timeout#,rp_fail#,rp_succ#,rp_delay#;/sandbox-status/!flat:state;/probe-rt-s/!flat:seq,verdict#"
    watch: "/pod-probes/,/sandbox-status/,/probe-rt-"
  - name: pb_tr_rt
    type: store_effect
    # chronicle-source: modules/app/_chronicle/probe.uproc tk_r
    decision: {hex: ""}
    key_prefix: "/probe-rt-r/"
  - name: pb_tr_res
    type: store_effect
    # chronicle-source: modules/app/_chronicle/probe.uproc sm_res
    decision: {hex: ""}
  - name: pb_tr_out
    type: store_effect
    # chronicle-source: modules/app/_chronicle/probe.uproc sm_out
    decision: {hex: ""}
  - name: pb_tr_req
    type: store_effect
    # chronicle-source: modules/app/_chronicle/probe.uproc sm_req
    decision: {hex: ""}
  - name: pb_res
    type: store_source
    prefix: "/sandbox-exec-result/"
    paths: "."
  - name: pb_get
    type: store_effect
    # chronicle-source: modules/app/_chronicle/probe_collect.uproc cl_get
    decision: {hex: ""}
    flat: 1
    ints: "inflight,fails,oks,verdict,fail_n,succ_n"
  - name: pb_dreq
    type: store_effect
    # chronicle-source: modules/app/_chronicle/probe_collect.uproc cl_req
    decision: {hex: ""}
  - name: pb_dres
    type: store_effect
    # chronicle-source: modules/app/_chronicle/probe_collect.uproc cl_res
    decision: {hex: ""}
  - name: pb_dout
    type: store_effect
    # chronicle-source: modules/app/_chronicle/probe_collect.uproc cl_out
    decision: {hex: ""}
  - name: pb_fold
    type: store_effect
    # chronicle-source: modules/app/_chronicle/probe_collect.uproc cl_fold
    decision: {hex: ""}
  - name: pb_pods
    type: store_source
    prefix: "/pod-probes/"
    related: "/probe-rt-l/!flat:seq,verdict#;/probe-rt-r/!flat:seq,verdict#;/probe-rt-s/!flat:seq,verdict#"
    watch: "/probe-rt-"
  - name: pb_pub
    type: store_effect
    # chronicle-source: modules/app/_chronicle/probe_collect.uproc pub
    decision: {hex: ""}
    key_prefix: "/probe-status/"
  - name: pb_gone
    type: store_source
    prefix: "/probe-status/"
    unless: "/pod-probes/"
  - name: pb_gone_e
    type: store_effect
    # chronicle-source: modules/app/_chronicle/probe_collect.uproc gone
    decision: {hex: "000b0000002f000100020100000040010000001004000000000000004002000000010002030000004003000000120000400400000041"}
    key_prefix: "/probe-status/"
  - name: pj_source
    type: store_source
    prefix: "/pod-specs/"
    flat: 1
    paths: "cmd,rootfs,iso,net,tasks,graph,image,args,env,workdir,cpu,mem,eph,pod"
    related: "/pod-resolved/:rootfs,cmd,env,workdir,user,user!uidnum;/pod-specs/:ruid,rgid,nonroot,cfgerr,gate#;/pod-init/~:done#;/sandbox-status/:state"
    watch: "/pod-"
  - name: pj_sandbox
    type: store_effect
    # chronicle-source: modules/app/_chronicle/pod_project.uproc art
    decision: {hex: ""}
    key_prefix: "/"
  - name: pj_runtime
    type: store_effect
    # chronicle-source: modules/app/_chronicle/pod_project.uproc rt
    decision: {hex: "000c0000003a000100020100000040010000001006000000000000004002000000010002fe000000021e00000040030000001206007365656e3d31400400000041"}
    key_prefix: "/pod-runtime/"
  - name: pj_msource
    type: store_source
    prefix: "/pod-specs/"
    flat: 1
    paths: "cmd,rootfs,iso,net,tasks,graph,image,args,env,workdir,cpu,mem,eph,pod"
    related: "/pod-resolved/:rootfs"
    watch: "/pod-resolved/"
  - name: pj_metal
    type: store_effect
    # chronicle-source: modules/app/_chronicle/pod_project.uproc mtl
    decision: {hex: ""}
    key_prefix: "/metal-sandboxes/"
  # ── image: a reference resolved to a rootfs and an argv ──────────────
  - name: pi_source
    type: store_source
    prefix: "/pod-specs/"
    flat: 1
    paths: "image,image!reg,image!repo,image!tag,image!pin,image!ikey,rootfs,cmd,pull,pod,args"
    watch: "/image-digests/,/image-rootfs/,/image-config/,/image-pull-failed/"
  - name: pi_requests
    type: store_effect
    # chronicle-source: modules/app/_chronicle/pod_image.uproc rq
    decision: {hex: ""}
    key_prefix: "/image-requests/"
  - name: pi_digest
    type: store_effect
    # chronicle-source: modules/app/_chronicle/pod_image.uproc ad
    decision: {hex: "01060000001100010002fe000000021f00000012000020000b0000002f0001000201000000400100000010000000000000000040020000001200004003000000010002fe00000040fe000000410d00000038000100020100000040010000001001000000000000004002000000010002fe000000021f0000004003000000010002fe00000040fe00000041"}
    key_prefix: "/image-digests/"
    flat: 1
    paths: "digest,refused"
  - name: pi_rootfs
    type: store_effect
    # chronicle-source: modules/app/_chronicle/pod_image.uproc ar
    decision: {hex: ""}
    # The rootfs read, or the Pod's event when its image cannot be had.
    key_prefix: "/"
    flat: 1
    paths: "state,path"
  - name: pi_config
    type: store_effect
    # chronicle-source: modules/app/_chronicle/pod_image.uproc ac
    decision: {hex: ""}
    # The config read, or the pull's failure (/image-pull-failed/).
    key_prefix: "/"
    flat: 1
    paths: "entrypoint!argv,cmd!argv,env,workdir,user,fails,code,why"
  - name: pi_resolved
    type: store_effect
    # chronicle-source: modules/app/_chronicle/pod_image.uproc rs
    decision: {hex: ""}
    # The resolution, or the Pod's event while its pull is failing.
    key_prefix: "/"
  # ── lifecycle ────────────────────────────────────────────────────────
  - name: pl_source
    type: store_source
    prefix: "/pod-runtime/"
    flat: 1
    ints: "kill_phase,kill_deadline,backoff_until,run_started,paused_since,restarts,was_terminal"
    now: 1
    due: "kill_deadline,backoff_until"
    related: "/pod-specs/:cmd,desired,restart,rootfs,graph,grace#;/sandbox-status/:state,code;/probe-status/:live;/sandboxes/:cmd;/pod-init/~:failed"
    watch: "/pod-specs/,/sandbox-status/,/probe-status/,/sandboxes/"
  - name: pl_runtime
    type: store_effect
    # chronicle-source: modules/app/_chronicle/pod_lifecycle.uproc st
    decision: {hex: ""}
    key_prefix: "/pod-runtime/"
  - name: pl_kill
    type: store_effect
    # chronicle-source: modules/app/_chronicle/pod_effect.uproc kl
    decision: {hex: ""}
    key_prefix: "/sandbox-kill/"
  - name: pl_sandbox
    type: store_effect
    # chronicle-source: modules/app/_chronicle/pod_effect.uproc sb
    decision: {hex: ""}
    key_prefix: "/sandboxes/"
  - name: pl_metal
    type: store_effect
    # chronicle-source: modules/app/_chronicle/pod_effect.uproc mt
    decision: {hex: ""}
    key_prefix: "/metal-sandboxes/"
  - name: pl_status
    type: store_effect
    # chronicle-source: modules/app/_chronicle/pod_effect.uproc st
    decision: {hex: ""}
    key_prefix: "/pod-lifecycle-status/"
  - name: pl_events
    type: store_effect
    # chronicle-source: modules/app/_chronicle/pod_effect.uproc ev
    decision: {hex: ""}
    key_prefix: "/events/"
  # ── prune ────────────────────────────────────────────────────────────
  - name: pr_source
    type: store_source
    prefix: "/pod-runtime/"
    related: "/sandbox-status/!flat:state;/metal-sandboxes/!flat:graph"
    watch: "/pod-specs/,/sandbox-status/"
  - name: pr_exists
    type: store_effect
    # chronicle-source: modules/app/_chronicle/pod_project.uproc ak
    decision: {hex: "00140000004600010002010000004001000000100200000000000000400200000001000203000000400300000001000203000000010002460000000100025000000042031e1f2040fe00000041"}
    key_prefix: "/pod-specs/"
  - name: pr_drop
    type: store_effect
    # chronicle-source: modules/app/_chronicle/pod_project.uproc pr
    decision: {hex: ""}
    key_prefix: "/"
  # Endpoints is PARAMS: Services JOIN the namespace's Pods with the label
  # selector as the join predicate and the probe runner's readiness overriding
  # the static field -> /endpointslices/<ns>/<svc>/<pod>; a slice whose Pod is
  # gone is pruned; and list_children over the slices materialises
  # /endpoints/<ns>/<svc> = "<pod>=<ip>,…" — the document the consumers parse,
  # unchanged. Params from modules/app/_chronicle/endpoints.uproc.
  - name: ep_pairs
    type: store_scan
    prefix: "/services/"
    paths: "spec.selector"
    join: "/pods/"
    join_scoped: 2
    join_match: "metadata.labels:spec.selector"
    join_paths: "status.conditions[type=Ready].status,status.podIP,metadata.uid"
    watch: "/pods/,/probe-status/"
  - name: ep_probe
    type: store_effect
    # chronicle-source: modules/app/_chronicle/endpoints.uproc ak
    decision: {hex: ""}
    key_prefix: "/probe-status/"
    flat: 1
    paths: "ready"
  - name: ep_slices
    type: store_effect
    # chronicle-source: modules/app/_chronicle/endpoints.uproc sl
    decision: {hex: ""}
    key_prefix: "/endpointslices/"
  - name: ep_sl_source
    type: store_source
    prefix: "/endpointslices/"
    related: "/services/^1:metadata.name"
    watch: "/pods/,/services/"
  - name: ep_podexists
    type: store_effect
    # chronicle-source: modules/app/_chronicle/endpoints.uproc ex
    decision: {hex: ""}
    key_prefix: "/pods/"
  - name: ep_collect
    type: store_effect
    # chronicle-source: modules/app/_chronicle/endpoints.uproc pr
    decision: {hex: ""}
    key_prefix: "/endpointslices/"
  - name: ep_svcs
    type: store_source
    prefix: "/services/"
    paths: "spec.selector"
    list_children: "/endpointslices/"
    child_sep: "/"
    watch: "/endpointslices/"
  - name: ep_write
    type: store_effect
    # chronicle-source: modules/app/_chronicle/endpoints.uproc dc
    decision: {hex: ""}
    key_prefix: "/endpoints/"
# Self-edge: the reconciler's own output feeds its `changes` input, allocating a
# module-owned channel the store's namespace.change SUBSCRIBE pushes onto. The
# module never writes this output; it drains pushed events from the input.
wiring:
${SANDBOX_WIRE}
  - from: pb_spec.status
    to: pb_spec.changes
  - from: pb_spec.record_out
    to: pb_seed_l.request_in
  - from: pb_seed_l.response_out
    to: pb_seed_r.request_in
  - from: pb_tl.status
    to: pb_tl.changes
  - from: pb_tl.record_out
    to: pb_tl_rt.request_in
  - from: pb_tl_rt.response_out
    to: pb_tl_res.request_in
  - from: pb_tl_res.response_out
    to: pb_tl_out.request_in
  - from: pb_tl_out.response_out
    to: pb_tl_req.request_in
  - from: pb_tr.status
    to: pb_tr.changes
  - from: pb_tr.record_out
    to: pb_tr_rt.request_in
  - from: pb_tr_rt.response_out
    to: pb_tr_res.request_in
  - from: pb_tr_res.response_out
    to: pb_tr_out.request_in
  - from: pb_tr_out.response_out
    to: pb_tr_req.request_in
  - from: pb_res.status
    to: pb_res.changes
  - from: pb_res.record_out
    to: pb_get.request_in
  - from: pb_get.response_out
    to: pb_dreq.request_in
  - from: pb_dreq.response_out
    to: pb_dres.request_in
  - from: pb_dres.response_out
    to: pb_dout.request_in
  - from: pb_dout.response_out
    to: pb_fold.request_in
  - from: pb_pods.status
    to: pb_pods.changes
  - from: pb_pods.record_out
    to: pb_pub.request_in
  - from: pb_gone.status
    to: pb_gone.changes
  - from: pb_gone.record_out
    to: pb_gone_e.request_in
  - from: pj_source.status
    to: pj_source.changes
  - from: pj_source.record_out
    to: pj_sandbox.request_in
  - from: pj_sandbox.response_out
    to: pj_runtime.request_in
  - from: pj_msource.status
    to: pj_msource.changes
  - from: pj_msource.record_out
    to: pj_metal.request_in
  - from: pi_source.status
    to: pi_source.changes
  - from: pi_source.record_out
    to: pi_requests.request_in
  - from: pi_requests.response_out
    to: pi_digest.request_in
  - from: pi_digest.response_out
    to: pi_rootfs.request_in
  - from: pi_rootfs.response_out
    to: pi_config.request_in
  - from: pi_config.response_out
    to: pi_resolved.request_in
  - from: pl_source.status
    to: pl_source.changes
  - from: pl_source.record_out
    to: pl_runtime.request_in
  - from: pl_runtime.response_out
    to: pl_kill.request_in
  - from: pl_kill.response_out
    to: pl_sandbox.request_in
  - from: pl_sandbox.response_out
    to: pl_metal.request_in
  - from: pl_metal.response_out
    to: pl_status.request_in
  - from: pl_status.response_out
    to: pl_events.request_in
  - from: pr_source.status
    to: pr_source.changes
  - from: pr_source.record_out
    to: pr_exists.request_in
  - from: pr_exists.response_out
    to: pr_drop.request_in
  - from: ep_pairs.status
    to: ep_pairs.changes
  - from: ep_pairs.record_out
    to: ep_probe.request_in
  - from: ep_probe.response_out
    to: ep_slices.request_in
  - from: ep_sl_source.status
    to: ep_sl_source.changes
  - from: ep_sl_source.record_out
    to: ep_podexists.request_in
  - from: ep_podexists.response_out
    to: ep_collect.request_in
  - from: ep_svcs.status
    to: ep_svcs.changes
  - from: ep_svcs.record_out
    to: ep_write.request_in
YAML
# The runtime block, spliced in (the heredoc above is quoted).
python3 - "$D/graph.yaml" "$SANDBOX_MODS" "$SANDBOX_WIRE" <<'PY'
import sys
p, mods, wire = sys.argv[1:4]
s = open(p).read().replace("${SANDBOX_MODS}", mods).replace("${SANDBOX_WIRE}", wire)
open(p, "w").write(s)
PY
nc_build_workload "$ROOT" "$D/graph.yaml" "$D/config.bin" "$D/modules.bin"

echo "== 2. materialize a sleeper bundle + seed the service, pods, and pod-specs =="
mkdir -p "$D/slp"

# Service selects app=web.
store_put "/services/default/web" '{"metadata":{"name":"web"},"spec":{"selector":{"app":"web"}}}'

# web-ready: readiness /bin/true (flips 0->1). Static Ready condition seeded False,
# so inclusion can ONLY come from the probe override.
store_put "/pods/default/web-ready" '{"metadata":{"name":"web-ready","uid":"pod-ready","labels":{"app":"web"}},"status":{"podIP":"10.0.0.7","conditions":[{"type":"Ready","status":"False"}]}}'
store_put "/pod-specs/pod-ready" "cmd=/bin/sleep 60;desired=running"
store_put "/pod-probes/pod-ready" "rp_cmd=/bin/true;rp_period=1;rp_timeout=2;rp_fail=1;rp_succ=1"

# web-fail: readiness /bin/false (holds ready=0). Static Ready condition seeded
# TRUE, so exclusion can ONLY come from the probe override pulling it out.
store_put "/pods/default/web-fail" '{"metadata":{"name":"web-fail","uid":"pod-fail","labels":{"app":"web"}},"status":{"podIP":"10.0.0.8","conditions":[{"type":"Ready","status":"True"}]}}'
store_put "/pod-specs/pod-fail" "cmd=/bin/sleep 60;desired=running"
store_put "/pod-probes/pod-fail" "rp_cmd=/bin/false;rp_period=1;rp_timeout=2;rp_fail=1;rp_succ=1"

echo "== 3. run the pipeline (sandbox launch + probe cadence ~1s) =="
FLUXOR_STORE_DIR="$D" RUST_LOG="${RUST_LOG:-warn}" timeout 10 "$FLUXOR_RUNTIME" \
  --config "$D/config.bin" --modules "$D/modules.bin" >"$D/run.log" 2>&1 || true

echo "== 4. the probe chain produced a REAL readiness flip on web-ready =="
PR="$(store_last /probe-status/pod-ready)"
[ "$PR" = "live=1;ready=1" ] || fail "pod-ready should be live=1;ready=1, got '$PR'"
store_history /probe-status/pod-ready | head -1 | grep -q 'ready=0' \
  || fail "pod-ready readiness should have STARTED at 0 (proves itself via the probe)"
echo "   /probe-status/pod-ready: ready 0 -> 1"

PF="$(store_last /probe-status/pod-fail)"
case "$PF" in
  *ready=0) echo "   /probe-status/pod-fail: ready held at 0 (/bin/false)";;
  *) fail "pod-fail readiness should be held at 0, got '$PF'";;
esac

echo "== 5. the bridge: endpoints reflect the PROBE verdict, not the static field =="
EP="$(store_last /endpoints/default/web)"
# web-ready: static=false but probe=1 → IN.  web-fail: static=true but probe=0 → OUT.
[ "$EP" = "web-ready=10.0.0.7" ] \
  || fail "endpoints should be exactly 'web-ready=10.0.0.7' (probe override in AND out), got '$EP'"
echo "   /endpoints/default/web: $EP"

echo "== 6. web-ready APPEARED only after the probe passed (disappear->appear) =="
# Every written endpoints doc: web-ready must not have been present before its
# probe flipped (static ready=false kept it out); the final doc contains it.
if store_history /endpoints/default/web | grep -q 'web-fail'; then
  fail "web-fail must NEVER enter the endpoint set (its readiness probe fails)"
fi
store_history /endpoints/default/web | tail -1 | grep -q 'web-ready=10.0.0.7' \
  || fail "web-ready must be in the final endpoint set once its probe passed"
echo "   web-fail never appeared; web-ready appeared on the flip"

echo "== E2E green: readiness bridge closed — a real probe flip reaches Service endpoints via metadata.uid join =="
